Object.assign(SNIP,{});PRESET_NOTES["l13"]={"Ví dụ: Truy vấn tổng đoạn (chỉ số từ 1)": "S[0] = 0 nên truy vấn l = 1 không cần xử lý riêng. Mỗi truy vấn chỉ một phép trừ.", "Ví dụ: Hình vuông k × k có tổng lớn nhất": "Hình vuông 2 × 2 tốt nhất là góc dưới phải 5 + 6 + 8 + 9 = 28. Mỗi hình vuông tính bằng 4 ô của S.", "Ví dụ: Mảng hiệu, cộng v vào đoạn": "Ba thao tác chỉ sửa 6 ô của D. Cộng dồn D ở cuối cho lượng nước mỗi cây nhận: 2 3 3 11 1."};EX_HINTS["l13"]=[["Code mẫu đúng nhưng O(n · q).", "S[i] = S[i − 1] + a[i], tổng đoạn S[r] − S[l − 1].", "S là long long."], ["S[i][j] = S[i−1][j] + S[i][j−1] − S[i−1][j−1] + a[i][j].", "Hình vuông có góc dưới phải (i, j): S[i][j] − S[i−k][j] − S[i][j−k] + S[i−k][j−k].", "Giá trị có thể âm hết: khởi tạo best = LLONG_MIN."], ["Code mẫu cộng từng cây: O(n · m).", "Mảng hiệu: D[l] += v, D[r + 1] −= v, cuối cùng cộng dồn D.", "D dài n + 2."]];
